import assert from "node:assert/strict";
import { test } from "node:test";

import { JSDOM } from "jsdom";
import { act, createElement } from "react";
import { createRoot } from "react-dom/client";

import {
  FacilityOrganizationRead,
  FacilityOrganizationType,
} from "@/types/facilityOrganization/facilityOrganization";

import { useOrganizationSelection } from "./useOrganizationSelection";

function organization(id: string, name = id): FacilityOrganizationRead {
  return {
    id,
    name,
    description: "",
    org_type: FacilityOrganizationType.DEPT,
    active: true,
    level_cache: 0,
    has_children: false,
    created_at: "2026-01-01T00:00:00Z",
    updated_at: "2026-01-01T00:00:00Z",
    permissions: [],
  };
}

test("organization selection follows controlled IDs without effects and preserves unresolved IDs", async () => {
  const dom = new JSDOM("<!doctype html><div id='root'></div>");
  const globals = {
    window: dom.window,
    document: dom.window.document,
    IS_REACT_ACT_ENVIRONMENT: true,
  };
  const previousGlobals = new Map(
    Object.keys(globals).map((key) => [
      key,
      Object.getOwnPropertyDescriptor(globalThis, key),
    ]),
  );
  for (const [key, value] of Object.entries(globals)) {
    Object.defineProperty(globalThis, key, { value, configurable: true });
  }
  const changes: {
    ids: string[] | null;
    records: FacilityOrganizationRead[];
  }[] = [];
  let selection: ReturnType<typeof useOrganizationSelection>;
  const current = () => selection;
  let renders = 0;
  function Harness(props: {
    value?: string[] | null;
    currentOrganizations?: FacilityOrganizationRead[];
    singleSelection?: boolean;
  }) {
    renders++;
    selection = useOrganizationSelection({
      ...props,
      singleSelection: props.singleSelection ?? false,
      onChange: (ids, records) => changes.push({ ids, records: records ?? [] }),
    });
    return null;
  }

  const root = createRoot(dom.window.document.getElementById("root")!);
  const first = organization("first");
  const second = organization("second");
  try {
    await act(async () =>
      root.render(createElement(Harness, { value: [first.id] })),
    );
    assert.deepEqual(current().selectedIds, [first.id]);
    assert.deepEqual(current().selectedOrganizations, []);
    await act(async () => current().selectOrganization(second));
    assert.deepEqual(changes.at(-1)?.ids, [first.id, second.id]);
    // An ID whose label has not arrived must not disappear from the next edit.
    assert.deepEqual(current().selectedIds, [first.id]);

    await act(async () =>
      root.render(
        createElement(Harness, {
          value: [first.id, second.id],
          currentOrganizations: [first],
        }),
      ),
    );
    assert.deepEqual(current().selectedOrganizations, [first, second]);
    const beforeProps = renders;
    await act(async () =>
      root.render(
        createElement(Harness, {
          value: [second.id, first.id],
          currentOrganizations: [first],
        }),
      ),
    );
    assert.equal(
      renders,
      beforeProps + 1,
      "selection changes need no synchronization render",
    );
    assert.deepEqual(current().selectedOrganizations, [second, first]);
    assert.equal(
      changes.length,
      1,
      "receiving props must not echo a change to the parent",
    );

    await act(async () => current().selectOrganization({ ...second }));
    assert.equal(
      changes.length,
      1,
      "duplicate detection uses IDs rather than object identity",
    );
    await act(async () => current().removeOrganization(second.id));
    assert.deepEqual(changes.at(-1)?.ids, [first.id]);

    const renamed = organization(first.id, "Updated department");
    await act(async () =>
      root.render(
        createElement(Harness, {
          value: [first.id],
          currentOrganizations: [renamed],
        }),
      ),
    );
    assert.equal(current().selectedOrganizations[0].name, renamed.name);
    await act(async () =>
      root.render(
        createElement(Harness, {
          value: [first.id],
          currentOrganizations: [],
        }),
      ),
    );
    assert.deepEqual(
      current().selectedOrganizations,
      [renamed],
      "a temporary metadata gap keeps the latest label and removable row",
    );
    await act(async () => root.render(createElement(Harness, { value: null })));
    assert.deepEqual(current().selectedOrganizations, []);
    assert.equal(
      changes.length,
      2,
      "external resets must not emit another change",
    );

    // Callers such as CareTeamSheet deliberately omit value.
    await act(async () =>
      root.render(createElement(Harness, { key: "uncontrolled" })),
    );
    await act(async () => current().selectOrganization(first));
    await act(async () => current().selectOrganization(second));
    assert.deepEqual(current().selectedIds, [first.id, second.id]);
    await act(async () => current().removeOrganization(first.id));
    assert.deepEqual(current().selectedOrganizations, [second]);
    await act(async () => current().removeOrganization(second.id));
    assert.deepEqual(current().selectedOrganizations, []);
    assert.equal(changes.at(-1)?.ids, null);

    await act(async () =>
      root.render(
        createElement(Harness, {
          key: "single",
          singleSelection: true,
        }),
      ),
    );
    await act(async () => current().selectOrganization(first));
    await act(async () => current().selectOrganization(second));
    assert.deepEqual(current().selectedOrganizations, [second]);
    await act(async () => current().replaceSelection([first]));
    assert.deepEqual(current().selectedOrganizations, [first]);
  } finally {
    await act(async () => root.unmount());
    dom.window.close();
    for (const [key, descriptor] of previousGlobals) {
      if (descriptor) Object.defineProperty(globalThis, key, descriptor);
      else Reflect.deleteProperty(globalThis, key);
    }
  }
});
import careConfig from "@careConfig";

import {
  ApiCallOptions,
  ApiRoute,
  HTTPError,
  PaginatedResponse,
} from "@/Utils/request/types";
import { getResponseBody, makeHeaders, makeUrl } from "@/Utils/request/utils";
import { sleep } from "@/Utils/utils";

export async function callApi<Route extends ApiRoute<unknown, unknown>>(
  { baseUrl, path, method, noAuth, defaultQueryParams }: Route,
  options?: ApiCallOptions<Route>,
): Promise<Route["TRes"]> {
  const url = `${baseUrl ?? careConfig.apiUrl}${makeUrl(
    path,
    {
      ...(defaultQueryParams ?? {}),
      ...options?.queryParams,
    },
    options?.pathParams,
  )}`;

  const isFormData = options?.body instanceof FormData;

  const fetchOptions: RequestInit = {
    method,
    headers: makeHeaders(noAuth ?? false, options?.headers, isFormData),
    signal: options?.signal,
  };

  if (options?.body) {
    if (isFormData) {
      fetchOptions.body = options.body as FormData;
    } else {
      fetchOptions.body = JSON.stringify(options.body);
    }
  }

  let res: Response;

  try {
    res = await fetch(url, fetchOptions);
  } catch (error) {
    throw new Error("Network Error", { cause: error });
  }

  const data = await getResponseBody<Route["TRes"]>(res);

  if (!res.ok) {
    const isSilent =
      typeof options?.silent === "function"
        ? options.silent(res)
        : (options?.silent ?? false);

    throw new HTTPError({
      message: "Request Failed",
      status: res.status,
      silent: isSilent,
      cause: data as unknown as Record<string, unknown>,
    });
  }

  return data;
}

/**
 * Creates a TanStack Query compatible query function.
 *
 * Example:
 * ```tsx
 * const { data, isLoading } = useQuery({
 *   queryKey: ["prescription", consultationId],
 *   queryFn: query(MedicineRoutes.prescription, {
 *     pathParams: { consultationId },
 *     queryParams: {
 *       limit: 10,
 *       offset: 0,
 *     },
 *   }),
 * });
 * ```
 */
export default function query<Route extends ApiRoute<unknown, unknown>>(
  route: Route,
  options?: ApiCallOptions<Route>,
) {
  return ({ signal }: { signal: AbortSignal }) => {
    return callApi(route, { ...options, signal });
  };
}

/**
 * Creates a debounced TanStack Query compatible query function.
 *
 * Example:
 * ```tsx
 * const { data, isLoading } = useQuery({
 *   queryKey: ["patient-search", facilityId, search],
 *   queryFn: query.debounced(patientsApi.search, {
 *     pathParams: { facilityId },
 *     queryParams: { limit: 10, offset: 0, search },
 *   }),
 * });
 * ```
 *
 * The debounced query leverages TanStack Query's built-in cancellation through
 * `AbortSignal`. Here's how it works:
 *
 * 1. When a new query is triggered, TanStack Query automatically creates an
 * `AbortSignal`
 * 2. If a new query starts before the debounce delay finishes:
 *    - The previous signal is aborted automatically by TanStack Query
 *    - The previous `sleep` promise is cancelled
 *    - A new debounce timer starts
 *
 * No explicit cleanup is needed because:
 * - The `AbortSignal` is passed through to the underlying `fetch` call
 * - When aborted, both the `sleep` promise and the fetch request are cancelled automatically
 * - TanStack Query handles the abortion and cleanup of previous in-flight requests
 */
const debouncedQuery = <Route extends ApiRoute<unknown, unknown>>(
  route: Route,
  options?: ApiCallOptions<Route> & { debounceInterval?: number },
) => {
  return async ({ signal }: { signal: AbortSignal }) => {
    await sleep(options?.debounceInterval ?? 500);
    return query(route, { ...options })({ signal });
  };
};
query.debounced = debouncedQuery;

/**
 * Creates a TanStack Query compatible paginated query function.
 *
 * This function is useful for fetching paginated data from an API.
 * It will fetch all pages of data and return a single array of results.
 *
 * To disable pagination, set the `maxPages` option to `1`.
 * Leaving it unset will fetch all pages.
 *
 * Example:
 * ```tsx
 * const { data, isLoading } = useQuery({
 *   queryKey: ["patient-search", facilityId, search],
 *   queryFn: query.paginated(patientsApi.search, {
 *     pathParams: { facilityId },
 *     queryParams: { limit: 10, offset: 0, search },
 *   }),
 * });
 * ```
 */
const paginatedQuery = <
  Route extends ApiRoute<PaginatedResponse<unknown>, unknown>,
>(
  route: Route,
  options?: ApiCallOptions<Route> & { pageSize?: number; maxPages?: number },
) => {
  return async ({ signal }: { signal: AbortSignal }) => {
    const items: Route["TRes"]["results"] = [];
    let hasNextPage = true;
    let page = 0;
    let count = 0;

    const pageSize =
      options?.pageSize ?? careConfig.pagination.limitOffset.maxLimit;

    while (hasNextPage) {
      const res = await query(route, {
        ...options,
        queryParams: {
          limit: pageSize,
          offset: page * pageSize,
          ...options?.queryParams,
        },
      })({ signal });

      count = res.count;
      items.push(...res.results);

      if (options?.maxPages && page >= options.maxPages - 1) {
        hasNextPage = false;
      }

      if (items.length >= res.count) {
        hasNextPage = false;
      }

      page++;
    }

    return {
      count,
      results: items,
    };
  };
};
query.paginated = paginatedQuery;
