import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { extractQuestions } from "@/components/QuestionnaireV2/shared/questionnaireImport";
import { Question } from "@/types/questionnaire/question";

/** Max accepted size for a fetched questionnaire JSON (bytes/characters). */
const MAX_IMPORT_SIZE = 5_000_000;

async function fetchQuestionnaire(url: string, signal: AbortSignal) {
  const response = await fetch(url, {
    signal: AbortSignal.any([signal, AbortSignal.timeout(10_000)]),
  });
  if (!response.ok) throw new Error("Failed to fetch questionnaire");
  const contentType = response.headers.get("content-type") ?? "";
  if (contentType && !/json|text/i.test(contentType)) {
    throw new Error("Unexpected content type");
  }
  if (Number(response.headers.get("content-length")) > MAX_IMPORT_SIZE) {
    throw new Error("Questionnaire file too large");
  }
  const text = await response.text();
  if (text.length > MAX_IMPORT_SIZE) {
    throw new Error("Questionnaire file too large");
  }
  return text;
}

/** Reads external JSON into an import preview, never into the query cache.
 * A source change or unmount invalidates both fetches and uncancellable
 * File.text reads, so only this session's latest request may finish. */
export function useQuestionImport(onReady: () => void) {
  const { t } = useTranslation();
  const activeImport = useRef<AbortController | null>(null);
  const [pendingQuestions, setPendingQuestions] = useState<Question[] | null>(
    null,
  );
  const [isFetching, setIsFetching] = useState(false);
  const [fileError, setFileError] = useState("");

  useEffect(
    () => () => {
      activeImport.current?.abort();
      activeImport.current = null;
    },
    [],
  );

  const cancelImport = () => {
    activeImport.current?.abort();
    activeImport.current = null;
    setIsFetching(false);
    setPendingQuestions(null);
    setFileError("");
  };

  const readImport = async (
    source: "file" | "url",
    read: (signal: AbortSignal) => Promise<string>,
  ) => {
    cancelImport();
    const controller = new AbortController();
    activeImport.current = controller;
    setIsFetching(source === "url");
    const isCurrent = () =>
      activeImport.current === controller && !controller.signal.aborted;
    try {
      const text = await read(controller.signal);
      if (!isCurrent()) return;
      const data: unknown = JSON.parse(text);
      const questions = extractQuestions(data);
      if (!questions) {
        if (source === "file") setFileError(t("invalid_json"));
        else toast.error(t("invalid_json"));
        return;
      }
      setPendingQuestions(questions);
      onReady();
    } catch {
      if (!isCurrent()) return;
      if (source === "file") setFileError(t("invalid_json"));
      else toast.error(t("failed_to_import_questionnaire"));
    } finally {
      if (isCurrent()) {
        activeImport.current = null;
        setIsFetching(false);
      }
    }
  };

  return {
    pendingQuestions,
    isFetching,
    fileError,
    cancelImport,
    importFile: (file: File) => readImport("file", () => file.text()),
    importUrl: (url: string) =>
      readImport("url", (signal) => fetchQuestionnaire(url, signal)),
  };
}
import assert from "node:assert/strict";
import { test } from "node:test";

import { createInstance } from "i18next";
import { JSDOM } from "jsdom";
import { act, createElement } from "react";
import { createRoot } from "react-dom/client";
import { I18nextProvider } from "react-i18next";

import { useQuestionImport } from "./useQuestionImport";

function deferredText() {
  let resolve!: (text: string) => void;
  const promise = new Promise<string>((done) => (resolve = done));
  return { promise, resolve };
}

const questionnaireJson = (text: string) =>
  JSON.stringify({
    questions: [{ link_id: "question", type: "string", text }],
  });

async function mountImport(onReady: () => void) {
  const dom = new JSDOM("<!doctype html><div id='root'></div>");
  const globals = {
    window: dom.window,
    document: dom.window.document,
    IS_REACT_ACT_ENVIRONMENT: true,
  };
  const previousGlobals = new Map(
    Object.keys(globals).map((key) => [
      key,
      Object.getOwnPropertyDescriptor(globalThis, key),
    ]),
  );
  for (const [key, value] of Object.entries(globals)) {
    Object.defineProperty(globalThis, key, { value, configurable: true });
  }
  const i18n = createInstance();
  await i18n.init({ lng: "en", resources: {}, initAsync: false });
  let state!: ReturnType<typeof useQuestionImport>;
  function Harness() {
    state = useQuestionImport(onReady);
    return null;
  }
  const root = createRoot(dom.window.document.getElementById("root")!);
  const render = async (show: boolean) => {
    await act(async () => {
      root.render(
        createElement(
          I18nextProvider,
          { i18n },
          show ? createElement(Harness) : null,
        ),
      );
    });
  };
  await render(true);
  return {
    current: () => state,
    render,
    async cleanup() {
      await act(async () => root.unmount());
      dom.window.close();
      for (const [key, descriptor] of previousGlobals) {
        if (descriptor) Object.defineProperty(globalThis, key, descriptor);
        else Reflect.deleteProperty(globalThis, key);
      }
    },
  };
}

test("a newer source owns pending questions even when an old fetch ignores abort", async (t) => {
  const ready = t.mock.fn();
  const view = await mountImport(ready);
  t.after(() => view.cleanup());
  const oldText = deferredText();
  let signal: AbortSignal | undefined;
  t.mock.method(
    globalThis,
    "fetch",
    async (_url: RequestInfo | URL, options: RequestInit) => {
      signal = options.signal ?? undefined;
      const response = new Response("", {
        headers: { "content-type": "application/json" },
      });
      response.text = () => oldText.promise;
      return response;
    },
  );
  let pending!: Promise<void>;
  await act(async () => {
    pending = view.current().importUrl("https://example.com/old.json");
  });
  assert.equal(view.current().isFetching, true);
  await act(async () => {
    await view
      .current()
      .importFile(new File([questionnaireJson("New file")], "new.json"));
  });
  assert.equal(signal?.aborted, true);
  assert.equal(view.current().isFetching, false);
  assert.equal(view.current().pendingQuestions?.[0].text, "New file");
  await act(async () => {
    oldText.resolve(questionnaireJson("Old URL"));
    await pending;
  });
  assert.equal(view.current().pendingQuestions?.[0].text, "New file");
  assert.equal(ready.mock.callCount(), 1);
});

test("cancelled file reads cannot finish into a newly opened import session", async (t) => {
  const ready = t.mock.fn();
  const view = await mountImport(ready);
  t.after(() => view.cleanup());
  const oldText = deferredText();
  const file = new File([], "old.json");
  file.text = () => oldText.promise;
  let pending!: Promise<void>;
  await act(async () => {
    pending = view.current().importFile(file);
  });
  await view.render(false);
  await view.render(true);
  await act(async () => {
    oldText.resolve(questionnaireJson("Old file"));
    await pending;
  });
  assert.deepEqual(view.current().pendingQuestions, null);
  assert.equal(view.current().fileError, "");
  assert.equal(ready.mock.callCount(), 0);
});

test("an old URL completion cannot stop a newer request's loading state", async (t) => {
  const ready = t.mock.fn();
  const view = await mountImport(ready);
  t.after(() => view.cleanup());
  const first = deferredText();
  const second = deferredText();
  t.mock.method(globalThis, "fetch", async (url: string) => {
    const response = new Response("", {
      headers: { "content-type": "application/json" },
    });
    response.text = () => (url.endsWith("first") ? first : second).promise;
    return response;
  });
  let oldRequest!: Promise<void>;
  let newRequest!: Promise<void>;
  await act(async () => {
    oldRequest = view.current().importUrl("https://example.com/first");
  });
  await act(async () => {
    newRequest = view.current().importUrl("https://example.com/second");
  });
  await act(async () => {
    first.resolve(questionnaireJson("Old URL"));
    await oldRequest;
  });
  assert.equal(view.current().isFetching, true);
  assert.deepEqual(view.current().pendingQuestions, null);
  await act(async () => {
    second.resolve(questionnaireJson("Current URL"));
    await newRequest;
  });
  assert.equal(view.current().isFetching, false);
  assert.equal(view.current().pendingQuestions?.[0].text, "Current URL");
  assert.equal(ready.mock.callCount(), 1);
});
