import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { regenerateQuestionIdsWithMap } from "@/components/QuestionnaireV2/shared/questionTree";

import { Question } from "@/types/questionnaire/question";

import { ImportQuestionsFilePicker } from "./ImportQuestionsFilePicker";
import { useQuestionImport } from "./useQuestionImport";

type ImportMode = "file" | "url";
type ImportStep = "select" | "confirm";

interface ImportQuestionsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onImport: (questions: Question[], linkIdMap: Map<string, string>) => void;
}

export function ImportQuestionsDialog({
  open,
  onOpenChange,
  onImport,
}: ImportQuestionsDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        {/* Each opening owns a fresh import session. Closing from the parent
            also clears pending data and aborts its work when it unmounts. */}
        {open && (
          <ImportQuestionsContent
            onClose={() => onOpenChange(false)}
            onImport={onImport}
          />
        )}
      </DialogContent>
    </Dialog>
  );
}

interface ImportQuestionsContentProps {
  onClose: () => void;
  onImport: ImportQuestionsDialogProps["onImport"];
}

function ImportQuestionsContent({
  onClose,
  onImport,
}: ImportQuestionsContentProps) {
  const { t } = useTranslation();
  const [step, setStep] = useState<ImportStep>("select");
  const [mode, setMode] = useState<ImportMode>("file");
  const [url, setUrl] = useState("");
  const [urlError, setUrlError] = useState<string>();
  const {
    pendingQuestions,
    isFetching,
    fileError,
    importFile,
    importUrl,
    cancelImport,
  } = useQuestionImport(() => setStep("confirm"));

  // http(s) only — z.url() alone admits javascript:, file:, data: etc.
  const urlSchema = z
    .url(t("invalid_url"))
    .refine(
      (value) => ["http:", "https:"].includes(new URL(value).protocol),
      t("invalid_url"),
    );

  const handleImportFromUrl = () => {
    const result = urlSchema.safeParse(url);
    if (!result.success) {
      setUrlError(result.error.issues[0]?.message ?? t("invalid_url"));
      return;
    }
    setUrlError(undefined);
    void importUrl(url);
  };

  const handleConfirm = () => {
    if (!pendingQuestions) return;
    try {
      const { questions, linkIdMap } =
        regenerateQuestionIdsWithMap(pendingQuestions);
      onImport(questions, linkIdMap);
    } catch {
      // Insurance against shapes the validators didn't anticipate — a toast
      // beats an uncaught throw in an onClick (which the page ErrorBoundary
      // can't catch and just leaves a dead button).
      toast.error(t("invalid_json"));
      return;
    }
    onClose();
  };

  return (
    <>
      <DialogHeader>
        <DialogTitle>{t("import_questionnaire")}</DialogTitle>
      </DialogHeader>

      {step === "select" ? (
        <div className="space-y-4">
          <Select
            value={mode}
            onValueChange={(value) => {
              cancelImport();
              setMode(value as ImportMode);
            }}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="file">{t("import_from_json_file")}</SelectItem>
              <SelectItem value="url">{t("import_from_url")}</SelectItem>
            </SelectContent>
          </Select>

          {mode === "file" ? (
            <ImportQuestionsFilePicker
              error={fileError}
              onFile={(file) => void importFile(file)}
            />
          ) : (
            <div className="space-y-2">
              <Label htmlFor="import-questions-url">
                {t("paste_questionnaire_json_url")}
              </Label>
              <Input
                id="import-questions-url"
                value={url}
                onChange={(e) => {
                  cancelImport();
                  setUrl(e.target.value);
                  setUrlError(undefined);
                }}
                // eslint-disable-next-line i18next/no-literal-string -- example URL, not translatable prose
                placeholder="https://example.com/questionnaire.json"
              />
              {urlError && (
                <p className="text-sm text-destructive">{urlError}</p>
              )}
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-4">
          <p className="text-sm text-gray-700">
            {t("questions_count")}: {pendingQuestions?.length ?? 0}
          </p>
          <Alert variant="destructive">
            <TriangleAlert className="size-4" />
            <AlertTitle>{t("warning")}</AlertTitle>
            <AlertDescription>
              {t("all_existing_data_will_be_replaced")}
            </AlertDescription>
          </Alert>
        </div>
      )}

      <DialogFooter>
        {step === "select" ? (
          <>
            <Button type="button" variant="outline" onClick={onClose}>
              {t("cancel")}
            </Button>
            {/* Always render the primary action so the footer keeps the
                  Cancel/primary rhythm in both modes; in file mode the
                  dropzone drives the flow, so it stays disabled. */}
            <Button
              type="button"
              onClick={handleImportFromUrl}
              disabled={mode === "file" || isFetching || !url}
            >
              {isFetching ? t("importing") : t("import")}
            </Button>
          </>
        ) : (
          <>
            <Button
              type="button"
              variant="outline"
              onClick={() => setStep("select")}
            >
              {t("back")}
            </Button>
            <Button type="button" onClick={handleConfirm}>
              {t("import")}
            </Button>
          </>
        )}
      </DialogFooter>
    </>
  );
}
import { TFunction } from "i18next";
import { z } from "zod";

import {
  QUESTIONNAIRE_STATUSES,
  QuestionStatus,
} from "@/types/questionnaire/questionnaire";

/**
 * Backend slug bounds shared by create, detail and clone forms, slug
 * auto-generation, and the clone dialog's `-copy` suffix clamp.
 */
export const SLUG_MIN_LENGTH = 5;
export const SLUG_MAX_LENGTH = 50;

/**
 * The `title`/`slug`/`description`/`status` validation shared by the three
 * questionnaire identity forms: the detail page uses it as-is, the create
 * page `.extend`s it with `subject_type`, and the clone dialog `.pick`s
 * title+slug. Building it allocates fresh Zod objects, so consumers wrap
 * the call (plus any `.extend`/`.pick`) in `useMemo(..., [t])`.
 */
export function questionnaireBasicSchema(t: TFunction) {
  const characterCountMessage = t("character_count_validation", {
    min: SLUG_MIN_LENGTH,
    max: SLUG_MAX_LENGTH,
  });
  return z.object({
    title: z.string().min(1, t("field_required")),
    slug: z
      .string()
      .min(SLUG_MIN_LENGTH, characterCountMessage)
      .max(SLUG_MAX_LENGTH, characterCountMessage)
      .regex(/^[-\w]+$/, t("slug_format_message")),
    description: z.string(),
    status: z.enum(QUESTIONNAIRE_STATUSES),
  });
}

/** The fields `BasicInformationCard` renders — form value shapes that embed
 *  the card (detail, create) extend this. */
export interface BasicInfoFormValues {
  title: string;
  slug: string;
  description: string;
}

/** The detail page's form values; lives here (not in the page) so child
 *  components don't import their prop types from the page that renders them. */
export interface DetailFormValues extends BasicInfoFormValues {
  status: QuestionStatus;
}
import { expect, test, type Page } from "@playwright/test";
import { getFacilityId } from "tests/support/facilityId";

// The backend's SlugType accepts 5–50 characters. Keep this contract
// independent of the frontend schema so a changed bound cannot bless itself.

test.use({ storageState: "tests/.auth/user.json" });

/** Counts POST requests to the questionnaire create endpoint. */
function trackCreateRequests(page: Page) {
  const requests: string[] = [];
  page.on("request", (request) => {
    if (
      request.method() === "POST" &&
      /\/api\/v1\/questionnaire\/$/.test(new URL(request.url()).pathname)
    ) {
      requests.push(request.url());
    }
  });
  return requests;
}

test.describe("Questionnaire v2 create form validation", () => {
  test("an empty title blocks the save with field errors", async ({ page }) => {
    const facilityId = getFacilityId();
    const posts = trackCreateRequests(page);

    await page.goto(`/facility/${facilityId}/settings/questionnaires/new`);
    await page.getByRole("button", { name: "Save Questionnaire" }).click();

    await expect(page.getByText("This field is required")).toBeVisible();
    await expect(page).toHaveURL(/\/questionnaires\/new$/);
    expect(posts).toHaveLength(0);
  });

  test("slug bounds and format are enforced", async ({ page }) => {
    const facilityId = getFacilityId();
    const posts = trackCreateRequests(page);
    const title = `QV2 Slug Rules ${Date.now()} ${"x".repeat(60)}`;
    const slugInput = page.getByRole("textbox", { name: "Slug" });

    await page.goto(`/facility/${facilityId}/settings/questionnaires/new`);

    await test.step("Typing a title auto-generates a slug", async () => {
      await page
        .getByRole("textbox", { name: "Title" })
        .pressSequentially(title);
      await expect(slugInput).not.toHaveValue("");
      const generated = await slugInput.inputValue();
      expect(generated).toHaveLength(50);
      expect(generated).toMatch(/^[-\w]+$/);
    });

    for (const length of [4, 51]) {
      await test.step(`A ${length}-character slug fails the length rule`, async () => {
        await slugInput.fill("a".repeat(length));
        await page.getByRole("button", { name: "Save Questionnaire" }).click();
        await expect(
          page.getByText(
            "Must be atleast 5 characters and atmost 50 characters",
          ),
        ).toBeVisible();
        expect(posts).toHaveLength(0);
      });
    }

    await test.step("Invalid characters fail the format rule", async () => {
      await slugInput.fill("bad slug!");
      await page.getByRole("button", { name: "Save Questionnaire" }).click();
      // The hint text also shows the format sentence, so expect two matches
      // (description + error) once the rule fires.
      await expect(
        page.getByText(
          "Slug must only contain letters, numbers, underscores, and hyphens",
        ),
      ).toHaveCount(2);
      await expect(page).toHaveURL(/\/questionnaires\/new$/);
      expect(posts).toHaveLength(0);
    });
  });
});
import { faker } from "@faker-js/faker";
import { expect, test, type Page } from "@playwright/test";
import {
  createQuestionnaire,
  createQuestionnaireAndOpenBuilder,
  openQuestionBuilder,
} from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

const FAKE_URL = "https://questionnaire-fixtures.example/export.json";

async function openImportDialog(page: Page): Promise<void> {
  await page.getByRole("button", { name: "Import Questions" }).click();
  await expect(
    page.getByRole("dialog", { name: "Import Questionnaire" }),
  ).toBeVisible();
}

async function switchToUrlMode(page: Page): Promise<void> {
  const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });
  await dialog.getByRole("combobox").click();
  await page.getByRole("option", { name: "Import from URL" }).click();
  await expect(
    dialog.getByRole("textbox", { name: "Paste a questionnaire JSON URL" }),
  ).toBeVisible();
}

test.describe("Questionnaire v2 import via URL and malformed payloads", () => {
  test("imports questions fetched from a URL", async ({ page }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const qOne = `${faker.word.words(2)} One ${stamp}`;
    const qTwo = `${faker.word.words(2)} Two ${stamp}`;

    await page.route(FAKE_URL, (route) =>
      route.fulfill({
        contentType: "application/json",
        body: JSON.stringify({
          questions: [
            { text: qOne, type: "string", link_id: "u1" },
            { text: qTwo, type: "boolean", link_id: "u2" },
          ],
        }),
      }),
    );

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Url Import ${stamp}`,
    });
    await openImportDialog(page);
    await switchToUrlMode(page);

    const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });

    await test.step("Fetch, confirm and apply", async () => {
      await dialog
        .getByRole("textbox", { name: "Paste a questionnaire JSON URL" })
        .fill(FAKE_URL);
      await dialog.getByRole("button", { name: "Import", exact: true }).click();
      await expect(dialog.getByText("Question count: 2")).toBeVisible();
      await dialog.getByRole("button", { name: "Import", exact: true }).click();
      await expectToast(page, "Questionnaire Imported Successfully");
    });

    await test.step("The fetched questions landed in the builder", async () => {
      await expect(
        page.getByRole("textbox", { name: "Question Title" }),
      ).toHaveValue(qOne);
      await expect(
        page.getByRole("navigation").getByRole("button", { name: qTwo }),
      ).toBeVisible();
    });
  });

  test("a non-http(s) URL is rejected inline without fetching", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Bad Url ${Date.now()}`,
    });
    await openImportDialog(page);
    await switchToUrlMode(page);

    const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });
    await dialog
      .getByRole("textbox", { name: "Paste a questionnaire JSON URL" })
      .fill("ftp://example.com/questionnaire.json");
    await dialog.getByRole("button", { name: "Import", exact: true }).click();

    await expect(dialog.getByText("Please enter a valid url")).toBeVisible();
    // Still on the select step — no confirm summary appeared.
    await expect(dialog.getByText(/Question count/)).not.toBeVisible();
  });

  test("a fetched payload with an unknown question type is rejected", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await page.route(FAKE_URL, (route) =>
      route.fulfill({
        contentType: "application/json",
        body: JSON.stringify({
          questions: [{ text: "Bad", type: "radio", link_id: "x" }],
        }),
      }),
    );

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Bad Type ${Date.now()}`,
    });
    await openImportDialog(page);
    await switchToUrlMode(page);

    const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });
    await dialog
      .getByRole("textbox", { name: "Paste a questionnaire JSON URL" })
      .fill(FAKE_URL);
    await dialog.getByRole("button", { name: "Import", exact: true }).click();

    await expectToast(
      page,
      "Invalid JSON: please check the format and try again",
    );
    await expect(dialog.getByText(/Question count/)).not.toBeVisible();
  });

  test("a malformed JSON file shows the inline dropzone error", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Bad File ${Date.now()}`,
    });
    await openImportDialog(page);

    await page.locator('input[type="file"]').setInputFiles({
      name: "broken.json",
      mimeType: "application/json",
      buffer: Buffer.from("{not valid json"),
    });

    const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });
    await expect(
      dialog.getByText("Invalid JSON: please check the format and try again"),
    ).toBeVisible();
  });

  test("confirm step supports Back, and Cancel leaves the draft untouched", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Import Cancel ${Date.now()}`,
    });
    await openImportDialog(page);

    const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });

    await test.step("Reach the confirm step", async () => {
      await page.locator('input[type="file"]').setInputFiles({
        name: "ok.json",
        mimeType: "application/json",
        buffer: Buffer.from(
          JSON.stringify({
            questions: [{ text: "Discarded", type: "string", link_id: "d" }],
          }),
        ),
      });
      await expect(dialog.getByText("Question count: 1")).toBeVisible();
    });

    await test.step("Back returns to the picker", async () => {
      await dialog.getByRole("button", { name: "Back" }).click();
      await expect(
        dialog.getByText("Drag and drop file here or click to upload"),
      ).toBeVisible();
    });

    await test.step("Cancel closes without touching the empty draft", async () => {
      await dialog.getByRole("button", { name: "Cancel" }).click();
      await expect(dialog).not.toBeVisible();
      await expect(
        page.getByRole("button", { name: "Add First Question" }),
      ).toBeVisible();
      await expect(page.getByText("Discarded")).not.toBeVisible();
    });
  });

  test("the detail page's Import quick action deep-links with ?import=1", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await createQuestionnaire(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Import Deep Link ${Date.now()}`,
    });

    await test.step("The empty-state Import action opens the builder dialog", async () => {
      await page.getByRole("button", { name: "Import Questions" }).click();
      await expect(
        page.getByRole("dialog", { name: "Import Questionnaire" }),
      ).toBeVisible();
    });

    await test.step("The import param is stripped so refresh won't reopen", async () => {
      await expect(page).toHaveURL(/\/edit$/);
      await page.reload();
      await expect(
        page.getByRole("dialog", { name: "Import Questionnaire" }),
      ).not.toBeVisible();
      await expect(
        page.getByRole("button", { name: "Add First Question" }),
      ).toBeVisible();
    });
  });
});

test.describe("Questionnaire v2 import replaces an existing draft", () => {
  test("importing over saved questions replaces them after confirm", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const original = `Original ${stamp}`;
    const replacement = `Replacement ${stamp}`;

    await test.step("Author and save one question", async () => {
      await createQuestionnaire(page, {
        basePath: `/facility/${facilityId}/settings/questionnaires`,
        title: `QV2 Replace ${stamp}`,
      });
      await openQuestionBuilder(page);
      await page.getByRole("button", { name: "Add First Question" }).click();
      await page
        .getByRole("textbox", { name: "Question Title" })
        .pressSequentially(original);
      await page.getByRole("button", { name: "Save Changes" }).click();
      await expectToast(page, "Questionnaire updated successfully");
    });

    await test.step("Import a different question over it", async () => {
      // With questions present the Import affordance lives on the detail
      // page (quick action) — deep-link straight into the dialog.
      await page.goto(page.url().replace(/\/edit$/, "/edit?import=1"));
      const dialog = page.getByRole("dialog", { name: "Import Questionnaire" });
      await expect(dialog).toBeVisible();
      await page.locator('input[type="file"]').setInputFiles({
        name: "replacement.json",
        mimeType: "application/json",
        buffer: Buffer.from(
          JSON.stringify({
            questions: [{ text: replacement, type: "string", link_id: "r" }],
          }),
        ),
      });
      await expect(
        dialog.getByText("All existing data will be replaced"),
      ).toBeVisible();
      await dialog.getByRole("button", { name: "Import", exact: true }).click();
      await expectToast(page, "Questionnaire Imported Successfully");
    });

    await test.step("The draft now holds only the replacement", async () => {
      await expect(
        page.getByRole("textbox", { name: "Question Title" }),
      ).toHaveValue(replacement);
      await expect(page.getByText(original)).not.toBeVisible();
    });
  });
});

