import { z } from "zod";

import { QUESTION_TYPES, Question } from "@/types/questionnaire/question";
import { SUBJECT_TYPES } from "@/types/questionnaire/questionnaire";

/**
 * Recursively narrows an unknown question-ish object down to the fields the
 * importer needs. Validation must recurse: nested `questions` reach the
 * builder tree and the PUT body unmodified, so a malformed child (missing
 * `text`, or `questions` that isn't an array) would otherwise surface as a
 * crash in the confirm step or a save that silently does nothing.
 */
function isQuestionLike(value: unknown): value is Question {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as {
    text?: unknown;
    type?: unknown;
    link_id?: unknown;
    questions?: unknown;
    enable_when?: unknown;
  };
  if (typeof candidate.text !== "string") return false;
  // Membership, not just typeof: an unknown `type` (e.g. "radio") would flow
  // into builder state and crash the type picker's TYPE_ICONS lookup, then
  // be PUT to the API on save.
  if (
    typeof candidate.type !== "string" ||
    !(QUESTION_TYPES as readonly string[]).includes(candidate.type)
  ) {
    return false;
  }
  // link_id is optional (regenerateQuestionIds synthesizes fresh ones), but
  // when present it must be a string.
  if (
    candidate.link_id !== undefined &&
    typeof candidate.link_id !== "string"
  ) {
    return false;
  }
  if (
    candidate.enable_when != null &&
    (!Array.isArray(candidate.enable_when) ||
      !candidate.enable_when.every(
        (condition: unknown) =>
          typeof condition === "object" &&
          condition !== null &&
          "question" in condition &&
          typeof condition.question === "string",
      ))
  ) {
    return false;
  }
  if (candidate.questions !== undefined) {
    if (!Array.isArray(candidate.questions)) return false;
    return candidate.questions.every(isQuestionLike);
  }
  return true;
}

/**
 * Accepts either a bare `{ questions: [...] }` payload or a full
 * questionnaire export (which has a `questions` array alongside its other
 * fields) — both shapes are read the same way, through `.questions`.
 */
export function extractQuestions(
  data: unknown,
  { allowEmpty = false }: { allowEmpty?: boolean } = {},
): Question[] | null {
  if (typeof data !== "object" || data === null || !("questions" in data)) {
    return null;
  }
  const questions = (data as { questions: unknown }).questions;
  if (!Array.isArray(questions) || (!allowEmpty && questions.length === 0))
    return null;
  return questions.every(isQuestionLike) ? (questions as Question[]) : null;
}

/** Writable metadata from a full export; audit fields and scope are ignored. */
const importMetadataSchema = z.object({
  title: z.string().min(1),
  // Slug constraints belong to the editable confirmation form, so even an
  // older invalid slug can be corrected before any create request is sent.
  slug: z
    .string()
    .nullish()
    .transform((value) => value ?? ""),
  description: z.string().nullish(),
  subject_type: z.enum(SUBJECT_TYPES),
  version: z.union([z.string(), z.number()]).optional(),
  code: z
    .object({ system: z.string(), code: z.string(), display: z.string() })
    .nullish(),
  actions: z
    .array(
      z.object({
        condition: z.string(),
        instructions: z
          .array(
            z.object({
              slug: z.string().min(1),
              params: z.record(z.string(), z.unknown()),
              context: z.string().default("self"),
            }),
          )
          .default([]),
      }),
    )
    .nullish(),
});

export function parseQuestionnaireImport(data: unknown) {
  const metadata = importMetadataSchema.safeParse(data);
  const questions = extractQuestions(data, { allowEmpty: true });
  if (!metadata.success || !questions) return null;
  return { ...metadata.data, questions };
}

export type ImportedQuestionnaire = NonNullable<
  ReturnType<typeof parseQuestionnaireImport>
>;
import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  extractQuestions,
  parseQuestionnaireImport,
} from "./questionnaireImport";

const exported = {
  id: "source-questionnaire",
  title: "Clinical review",
  slug: "clinical-review",
  description: "Review symptoms",
  version: 1,
  subject_type: "encounter",
  status: "active",
  auth_context: "facility",
  facility: "source-facility",
  created_by: { username: "author" },
  code: null,
  questions: [
    { id: "source-question", link_id: "score", text: "Score", type: "integer" },
  ],
  actions: [
    {
      condition: "q_score > 5",
      instructions: [
        {
          slug: "show_message",
          params: { message: "Review score" },
          context: "self",
        },
      ],
    },
  ],
};

describe("questionnaire definition import", () => {
  it("keeps the writable definition and excludes source identity, scope and audit metadata", () => {
    const parsed = parseQuestionnaireImport(exported);
    assert.ok(parsed);
    assert.equal(parsed.slug, exported.slug);
    assert.equal(parsed.subject_type, "encounter");
    assert.deepEqual(parsed.actions, exported.actions);
    for (const field of [
      "id",
      "status",
      "auth_context",
      "facility",
      "created_by",
    ]) {
      assert.equal(field in parsed, false);
    }
  });

  it("allows correcting an invalid imported slug in the confirmation form", () => {
    assert.equal(
      parseQuestionnaireImport({ ...exported, slug: "old slug!" })?.slug,
      "old slug!",
    );
  });

  it("imports empty full drafts and lets legacy null slugs be corrected", () => {
    const parsed = parseQuestionnaireImport({
      ...exported,
      slug: null,
      questions: [],
    });
    assert.ok(parsed);
    assert.equal(parsed.slug, "");
    assert.deepEqual(parsed.questions, []);
    assert.equal(extractQuestions({ questions: [] }), null);
  });

  it("rejects malformed subjects, actions and nested questions before import", () => {
    assert.equal(
      parseQuestionnaireImport({ ...exported, subject_type: "unknown" }),
      null,
    );
    assert.equal(
      parseQuestionnaireImport({
        ...exported,
        actions: [{ condition: "True", instructions: [null] }],
      }),
      null,
    );
    for (const slug of [null, undefined, ""]) {
      assert.equal(
        parseQuestionnaireImport({
          ...exported,
          actions: [
            { condition: "True", instructions: [{ slug, params: {} }] },
          ],
        }),
        null,
      );
    }
    assert.equal(
      parseQuestionnaireImport({
        ...exported,
        questions: [
          {
            text: "Group",
            type: "group",
            questions: [{ text: "Bad child", type: "unknown" }],
          },
        ],
      }),
      null,
    );
  });

  it("rejects malformed condition references before regenerating question IDs", () => {
    for (const enable_when of [
      { question: "score" },
      [null],
      ["score"],
      [{}],
      [{ question: 123 }],
    ]) {
      assert.equal(
        parseQuestionnaireImport({
          ...exported,
          questions: [{ ...exported.questions[0], enable_when }],
        }),
        null,
      );
    }
    for (const enable_when of [
      undefined,
      null,
      [],
      [{ question: "score", operator: "greater", answer: 5 }],
    ]) {
      assert.ok(
        parseQuestionnaireImport({
          ...exported,
          questions: [{ ...exported.questions[0], enable_when }],
        }),
      );
    }
  });

  it("retains support for question-only files without treating them as full definitions", () => {
    const file = { questions: exported.questions };
    assert.deepEqual(extractQuestions(file), exported.questions);
    assert.equal(parseQuestionnaireImport(file), null);
  });
});
import { EnableWhen, Question } from "@/types/questionnaire/question";

/**
 * Pure question-tree utilities shared by manage/, builder/ and renderer/.
 * Nothing here touches builder state or React — reducer-coupled helpers stay
 * in builder/builderReducer.ts, presentation stays in QuestionTreeNav.tsx.
 */

export interface TreeItem {
  question: Question;
  number: string;
  children: TreeItem[];
}

/** Top-level questions get 1., 2., …; children get parent.child (1.1., 1.2.). */
export function numberQuestions(questions: Question[]): TreeItem[] {
  return questions.map((question, i) => ({
    question,
    number: `${i + 1}.`,
    children: (question.questions ?? []).map((child, j) => ({
      question: child,
      number: `${i + 1}.${j + 1}.`,
      children: [],
    })),
  }));
}

/** Pre-order depth-first search for the first question matching `predicate`
 *  — the one walk shape behind id lookup and the builder's save checks. */
export function findFirstQuestion(
  questions: Question[],
  predicate: (question: Question) => boolean,
): Question | undefined {
  for (const question of questions) {
    if (predicate(question)) return question;
    const found = findFirstQuestion(question.questions ?? [], predicate);
    if (found) return found;
  }
  return undefined;
}

/** Does `question` (or any of its descendants) have id `questionId`? */
function containsQuestion(question: Question, questionId: string): boolean {
  if (question.id === questionId) return true;
  return (question.questions ?? []).some((child) =>
    containsQuestion(child, questionId),
  );
}

/** Maps any question id (top-level or nested) to the index of its top-level
 *  ancestor in `questions` — so selecting a child in the tree nav pages to
 *  its containing top-level question. */
export function findTopLevelIndex(
  questions: Question[],
  questionId: string,
): number {
  const index = questions.findIndex((question) =>
    containsQuestion(question, questionId),
  );
  return index === -1 ? 0 : index;
}

/**
 * Looks up `questionId`'s own dotted number (e.g. "3." or "3.1.") from
 * `numberQuestions`'s two-level output. Returns undefined for ids nested
 * deeper than that (grandchildren+), since `numberQuestions` only numbers
 * top-level questions and their immediate children — callers should fall
 * back to the top-level ancestor's ordinal in that case.
 */
export function findQuestionNumber(
  questions: Question[],
  questionId: string,
): string | undefined {
  for (const item of numberQuestions(questions)) {
    if (item.question.id === questionId) return item.number;
