import { EnableWhen, Question } from "@/types/questionnaire/question";

/**
 * Pure question-tree utilities shared by manage/, builder/ and renderer/.
 * Nothing here touches builder state or React — reducer-coupled helpers stay
 * in builder/builderReducer.ts, presentation stays in QuestionTreeNav.tsx.
 */

export interface TreeItem {
  question: Question;
  number: string;
  children: TreeItem[];
}

/** Top-level questions get 1., 2., …; children get parent.child (1.1., 1.2.). */
export function numberQuestions(questions: Question[]): TreeItem[] {
  return questions.map((question, i) => ({
    question,
    number: `${i + 1}.`,
    children: (question.questions ?? []).map((child, j) => ({
      question: child,
      number: `${i + 1}.${j + 1}.`,
      children: [],
    })),
  }));
}

/** Pre-order depth-first search for the first question matching `predicate`
 *  — the one walk shape behind id lookup and the builder's save checks. */
export function findFirstQuestion(
  questions: Question[],
  predicate: (question: Question) => boolean,
): Question | undefined {
  for (const question of questions) {
    if (predicate(question)) return question;
    const found = findFirstQuestion(question.questions ?? [], predicate);
    if (found) return found;
  }
  return undefined;
}

/** Does `question` (or any of its descendants) have id `questionId`? */
function containsQuestion(question: Question, questionId: string): boolean {
  if (question.id === questionId) return true;
  return (question.questions ?? []).some((child) =>
    containsQuestion(child, questionId),
  );
}

/** Maps any question id (top-level or nested) to the index of its top-level
 *  ancestor in `questions` — so selecting a child in the tree nav pages to
 *  its containing top-level question. */
export function findTopLevelIndex(
  questions: Question[],
  questionId: string,
): number {
  const index = questions.findIndex((question) =>
    containsQuestion(question, questionId),
  );
  return index === -1 ? 0 : index;
}

/**
 * Looks up `questionId`'s own dotted number (e.g. "3." or "3.1.") from
 * `numberQuestions`'s two-level output. Returns undefined for ids nested
 * deeper than that (grandchildren+), since `numberQuestions` only numbers
 * top-level questions and their immediate children — callers should fall
 * back to the top-level ancestor's ordinal in that case.
 */
export function findQuestionNumber(
  questions: Question[],
  questionId: string,
): string | undefined {
  for (const item of numberQuestions(questions)) {
    if (item.question.id === questionId) return item.number;
    const child = item.children.find(
      (childItem) => childItem.question.id === questionId,
    );
    if (child) return child.number;
  }
  return undefined;
}

/** Questions that record answers (everything except `group` containers),
 *  at any depth — the count surfaces in canvas/outline "N questions" lines. */
export function countLeafQuestions(questions: Question[]): number {
  let count = 0;
  const walk = (list: Question[]) => {
    for (const question of list) {
      if (question.type === "group") walk(question.questions ?? []);
      else count += 1;
    }
  };
  walk(questions);
  return count;
}

/**
 * Deep-clones a question tree with fresh `id`s and `link_id`s, remapping
 * `enable_when` references through the whole copied tree. Missing or duplicate
 * link ids receive fresh values; only the first occurrence claims the remap.
 * `unmappedConditions` controls whether external references are dropped or
 * preserved for in-questionnaire duplication.
 */
/** A generated link id. Underscore, not hyphen: `q_<link_id>` must be a
 *  Python identifier for questionnaire actions to reference the answer
 *  (see `shared/actionExpression.ts`). */
export function freshLinkId(): string {
  return `Q_${crypto.randomUUID().slice(0, 8)}`;
}

export function regenerateQuestionIds(
  questions: Question[],
  options: { unmappedConditions?: "drop" | "keep" } = {},
): Question[] {
  return regenerateQuestionIdsWithMap(questions, options).questions;
}

/**
 * `regenerateQuestionIds` plus the old → new link_id map it built, for
 * callers that carry link_id references OUTSIDE the tree (the clone dialog
 * remaps the questionnaire's actions through it).
 */
export function regenerateQuestionIdsWithMap(
  questions: Question[],
  {
    unmappedConditions = "drop",
  }: { unmappedConditions?: "drop" | "keep" } = {},
): { questions: Question[]; linkIdMap: Map<string, string> } {
  const linkIdMap = new Map<string, string>();
  const mapLinkIds = (list: Question[]) => {
    for (const question of list) {
      if (question.link_id && !linkIdMap.has(question.link_id)) {
        linkIdMap.set(question.link_id, freshLinkId());
      }
      mapLinkIds(Array.isArray(question.questions) ? question.questions : []);
    }
  };
  mapLinkIds(questions);

  const remapEnableWhen = (
    enableWhen: EnableWhen[] | undefined,
  ): EnableWhen[] | undefined =>
    unmappedConditions === "keep"
      ? enableWhen?.map((condition) =>
          linkIdMap.has(condition.question)
            ? { ...condition, question: linkIdMap.get(condition.question)! }
            : condition,
        )
      : enableWhen
import { useQuery } from "@tanstack/react-query";
import { t } from "i18next";
import { useCallback, useRef, useState } from "react";

import CareIcon from "@/CAREUI/icons/CareIcon";

import Autocomplete from "@/components/ui/autocomplete";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";

import {
  scopedOptionLabel,
  useScopedValueSets,
} from "@/components/ValueSet/useScopedValueSets";
import { ValueSetEditor } from "@/components/ValueSet/ValueSetEditor";
import type { ValueSetFormState } from "@/components/ValueSet/ValueSetForm";

import {
  INSTANCE_VALUESET_SCOPE,
  ValueSetConfig,
  ValueSetRead,
  ValueSetScope,
  valueSetBinding,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";
import { mergeAutocompleteOptions } from "@/Utils/utils";

interface CreateValueSetProps {
  onValueSetChange?: (valueSet: ValueSetConfig | undefined) => void;
  value?: ValueSetConfig;
  /** Where the host is mounted. Inside a facility the picker lists that
   *  facility's sets alongside the instance ones, and the inline "Create
   *  value set" sheet files under the facility — only superusers may
   *  create instance-context sets. */
  scope?: ValueSetScope;
}

export function SelectOrCreateValueset({
  onValueSetChange,
  value,
  scope = INSTANCE_VALUESET_SCOPE,
}: CreateValueSetProps) {
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const editorState = useRef<ValueSetFormState>({
    isDirty: false,
    isSubmitting: false,
  });
  const handleEditorStateChange = useCallback((state: ValueSetFormState) => {
    editorState.current = state;
  }, []);
  const [pickedValueSet, setPickedValueSet] = useState<{
    binding: ValueSetConfig;
    valueset: ValueSetRead;
    scope: ValueSetScope;
  }>();
  const [searchQuery, setSearchQuery] = useState("");

  const { options, isFetching: isFetchingValuesets } = useScopedValueSets({
    facilityId: scope.facilityId,
    search: searchQuery,
  });

  // An imported questionnaire may reference a valueset by slug alone, and
  // expand_slug is the only endpoint that maps one back to its valueset.
  const { data: valuesetById, isLoading: isLoadingById } = useQuery({
    queryKey: ["valueset", value?.external_id],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: value?.external_id ?? "" },
    }),
    enabled: !!value?.external_id,
  });

  // Slug-only references are instance-level by contract (see
  // valueSetBinding), so this resolves without a facility on purpose.
  const { data: valuesetBySlug, isLoading: isLoadingBySlug } = useQuery({
    queryKey: ["valueset", "by-slug", value?.slug],
    queryFn: query(valueSetApi.expandSlug, {
      body: { slug: value?.slug ?? "", search: "", count: 1 },
    }),
    enabled: !value?.external_id && !!value?.slug,
  });

  const isLoadingCurrent = isLoadingById || isLoadingBySlug;

  // Resolve only the controlled binding. A previous question's fetched value
  // or optimistic pick must not leak into an empty or different binding.
  const resolvedValueSet = value?.external_id
    ? valuesetById
    : value?.slug
      ? valuesetBySlug?.valueset
      : undefined;
  const pickMatchesBinding = value?.external_id
    ? pickedValueSet?.binding.external_id === value.external_id
    : !!value?.slug &&
      !pickedValueSet?.binding.external_id &&
      pickedValueSet?.binding.slug === value.slug;
  const pickMatchesScope =
    pickedValueSet?.scope.authContext === scope.authContext &&
    pickedValueSet?.scope.facilityId === scope.facilityId;
  const currentValueSet =
    resolvedValueSet ??
    (pickMatchesBinding && pickMatchesScope
      ? pickedValueSet?.valueset
      : undefined);

  // The scope suffix is only meaningful where the two lists are merged —
  // an instance set and a facility override of it usually share a name.
  const valueSetOptions = options.map((option) => ({
    label:
      scope.authContext === "facility"
        ? scopedOptionLabel(option, t)
        : option.valueset.name,
    value: option.valueset.id,
  }));

  const handleValueSetChange = (selectedId: string) => {
    if (!selectedId) {
      setPickedValueSet(undefined);
      onValueSetChange?.(undefined);
      return;
    }
    const selected = options.find(
      (option) => option.valueset.id === selectedId,
    );
    if (selected) {
      // Show the pick immediately. An instance set is stored by slug alone,
      // so `value.external_id` is empty and the trigger would otherwise keep
      // displaying the previous set until expand_slug resolves.
      const binding = valueSetBinding(selected.valueset, selected.authContext);
      setPickedValueSet({ binding, valueset: selected.valueset, scope });
      onValueSetChange?.(binding);
      return;
    }
    // Re-picking the current (merged-in) entry keeps the stored reference
    // as is — its binding was decided when it was first chosen.
    if (currentValueSet?.id === selectedId && value) {
      onValueSetChange?.(value);
    }
  };

  const handleSheetOpenChange = (open: boolean) => {
    if (open) {
      editorState.current = { isDirty: false, isSubmitting: false };
      setIsSheetOpen(true);
      return;
    }
    if (editorState.current.isSubmitting) return;
    if (
      editorState.current.isDirty &&
      !window.confirm(t("unsaved_changes_warning"))
    ) {
      return;
    }
    setIsSheetOpen(false);
"}

