import { useTranslation } from "react-i18next";

import {
  QUESTION_TYPE_COMPONENTS,
  type RendererInputProps,
} from "./engine/questionTypeRegistry";
import { NoteControl } from "./NoteControl";
import { RepeatedQuestionInput } from "./RepeatedQuestionInput";
import { StructuredSlot } from "./StructuredSlot";

interface QuestionAnswerInputProps extends RendererInputProps {
  locked: boolean;
}

/** Choose the answer control without subscribing the question chrome to edits. */
export function QuestionAnswerInput({
  question,
  disabled,
  locked,
  inputId,
  labelId,
}: QuestionAnswerInputProps) {
  const { t } = useTranslation();
  if (question.type === "structured") {
    return <StructuredSlot question={question} disabled={disabled} />;
  }

  const InputComponent = QUESTION_TYPE_COMPONENTS[question.type];
  // Fixed-option choices manage their selected entries in one multi-select.
  // Keep the same precedence as ChoiceInput when a value set is also present.
  const isSelfManagedChoice =
    question.type === "choice" && !!question.answer_option?.length;
  if (
    InputComponent &&
    question.repeats === true &&
    question.type !== "display" &&
    !isSelfManagedChoice
  ) {
    return (
      <RepeatedQuestionInput
        question={question}
        disabled={disabled}
        locked={locked}
        inputId={inputId}
        labelId={labelId}
        component={InputComponent}
      />
    );
  }

  // Each control keeps its own border; the note sits behind a slim divider.
  return (
    <div className="flex items-stretch gap-0.5">
      <div className="min-w-0 flex-1">
        {InputComponent ? (
          <InputComponent
            question={question}
            disabled={disabled}
            inputId={inputId}
            labelId={labelId}
          />
        ) : (
          <p className="p-2 text-sm italic text-gray-400">
            {t("unsupported_question_type")}
          </p>
        )}
      </div>
      {question.type !== "display" && (
        <NoteControl questionId={question.id} locked={locked} />
      )}
    </div>
  );
}
import { ComponentType } from "react";

import { Question, QuestionType } from "@/types/questionnaire/question";

import { BooleanInput } from "./inputs/BooleanInput";
import { ChoiceInput } from "./inputs/ChoiceInput";
import { DateInput } from "./inputs/DateInput";
import { DateTimeQuestionInput } from "./inputs/DateTimeQuestionInput";
import { DisplayText } from "./inputs/DisplayText";
import { NumberInput } from "./inputs/NumberInput";
import { QuantityInput } from "./inputs/QuantityInput";
import { TextInput } from "./inputs/TextInput";
import { TimeInput } from "./inputs/TimeInput";

export interface RendererInputProps {
  question: Question;
  disabled: boolean;
  /** DOM id for the primary control — the question label's htmlFor target. */
  inputId: string;
  /** DOM id of the question label, for aria-labelledby on grouped controls. */
  labelId: string;
  /**
   * Index into `response.values` this input edits. Absent means single-entry
   * mode against `values[0]`.
   */
  valueIndex?: number;
}

export const QUESTION_TYPE_COMPONENTS: Partial<
  Record<QuestionType, ComponentType<RendererInputProps>>
> = {
  string: TextInput,
  text: TextInput,
  url: TextInput,
  decimal: NumberInput,
  integer: NumberInput,
  boolean: BooleanInput,
  choice: ChoiceInput,
  date: DateInput,
  dateTime: DateTimeQuestionInput,
  time: TimeInput,
  quantity: QuantityInput,
  display: DisplayText,
};
import { Plus, X } from "lucide-react";
import { useState, type ComponentType } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { NoteControl } from "./NoteControl";
import { emptyEntry } from "./engine/inputs/withEntryAt";
import type { RendererInputProps } from "./engine/questionTypeRegistry";
import { EMPTY_ROW_KEYS, dropRowKey, growRowKeys } from "./engine/rowKeys";
import { useQuestionResponse } from "./engine/store";

interface RepeatedQuestionInputProps extends RendererInputProps {
  locked: boolean;
  component: ComponentType<RendererInputProps>;
}

/** Own positional entries and stable row keys only for questions using repeats. */
export function RepeatedQuestionInput({
  question,
  disabled,
  locked,
  inputId,
  labelId,
  component: InputComponent,
}: RepeatedQuestionInputProps) {
  const { t } = useTranslation();
  const [response, updateResponse] = useQuestionResponse(question.id);
  const entryCount = Math.max(response?.values.length ?? 0, 1);
  const canRemoveEntries = (response?.values.length ?? 0) > 1;

  // Rows added by editing or draft restoration claim keys at render time.
  // Removing one carries every surviving row's local control state with it.
  const [rowKeys, setRowKeys] = useState(EMPTY_ROW_KEYS);
  const visibleRowKeys = growRowKeys(rowKeys, entryCount);
  if (visibleRowKeys !== rowKeys) setRowKeys(visibleRowKeys);

  const handleAddEntry = () => {
    const current = response?.values ?? [];
    // Materialize the placeholder too so Add never swallows the visible row.
    const next = current.length === 0 ? [emptyEntry()] : [...current];
    next.push(emptyEntry());
    updateResponse({ values: next });
  };
  const handleRemoveEntry = (index: number) => {
    setRowKeys((current) => dropRowKey(current, entryCount, index));
    updateResponse({
      values: (response?.values ?? []).filter((_, i) => i !== index),
    });
  };

  return (
    <div className="space-y-2">
      {Array.from({ length: entryCount }, (_, index) => (
        <div
          key={visibleRowKeys.keys[index]}
          className="flex items-center gap-2"
        >
          <div className="min-w-0 flex-1">
            <InputComponent
              question={question}
              disabled={disabled}
              inputId={index === 0 ? inputId : `${inputId}-${index}`}
              labelId={labelId}
              valueIndex={index}
            />
          </div>
          {canRemoveEntries && (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="shrink-0"
              disabled={disabled}
              onClick={() => handleRemoveEntry(index)}
              aria-label={t("remove")}
            >
              <X className="size-4" />
            </Button>
          )}
        </div>
      ))}
      <div className="flex items-center gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={disabled}
          onClick={handleAddEntry}
        >
          <Plus className="size-4" />
          {t("add_another")}
        </Button>
        <NoteControl questionId={question.id} locked={locked} />
      </div>
    </div>
  );
}
